<?php
require_once __DIR__.'/functions.php';require_role('buyer');$pdo=db();$s=$pdo->prepare("SELECT o.* FROM orders o WHERE o.client_id=? ORDER BY o.date DESC");$s->execute([user()['id']]);$orders=$s->fetchAll();$title='My Orders';include __DIR__.'/partials/header.php';?>
<section class="page"><div class="container"><div class="section-head"><div><span class="eyebrow">MY ACCOUNT</span><h1>My Orders</h1></div><a href="<?=BASE_URL?>/products.php" class="btn btn-light">Continue Shopping</a></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Amount</th><th>Order Status</th><th>Courier</th><th>Invoice</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b>#<?=e($o['id'])?></b></td><td><?=e($o['date'])?></td><td><b><?=money($o['price'])?></b></td><td><span class="status-pill status-<?=e($o['status'])?>"><?=e(ucfirst($o['status']))?></span></td><td><?=e($o['courier_status']??'Not sent')?></td><td><a class="btn btn-light" href="<?=BASE_URL?>/invoice.php?id=<?=$o['id']?>">View Invoice</a></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><div class="empty-state"><h2>No orders yet</h2><p class="muted">Your confirmed purchases will appear here.</p><a class="btn btn-primary" href="<?=BASE_URL?>/products.php">Start Shopping</a></div><?php endif;?></div></div></section><?php include __DIR__.'/partials/footer.php';?>
